typedef float rational_t;
typedef unsigned long uint64;

#define PSTRING_PCHUNK_NUMBER 4
#define assert(condition) ((void)0)

class pstring
{
private:
  uint64 pchunk[PSTRING_PCHUNK_NUMBER];
  void pack_string(const char *the_string);

public:
  pstring(const char *target_string)
  {
    assert(target_string != 0);
    pack_string(target_string);
  }

  bool operator == (const pstring &check_me) const
  {
    assert(check_me.is_set());

    for (unsigned i=0; i<PSTRING_PCHUNK_NUMBER; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }

  bool is_set() const;
};

class stringx
{
  char *data;
};

class vector3d
{
public:
  rational_t x;
  rational_t y;
  rational_t z;

  vector3d &operator=(const vector3d &value)
  {
    x = value.x;
    y = value.y;
    z = value.z;
    return *this;
  }
};

class generic_interface
{
public:
  virtual ~generic_interface();
  virtual bool get_ifc_num(const pstring &, rational_t &);
  virtual bool set_ifc_num(const pstring &, rational_t);
  virtual bool get_ifc_vec(const pstring &, vector3d &);
  virtual bool set_ifc_vec(const pstring &, const vector3d &);
  virtual bool get_ifc_str(const pstring &, stringx &);
  virtual bool set_ifc_str(const pstring &, const stringx &);
};

class entity;

class entity_interface : public generic_interface
{
protected:
  entity *my_entity;
};

class script_data_interface : public entity_interface
{
protected:
  rational_t num_1;
  rational_t num_2;
  rational_t num_3;
  rational_t num_4;
  rational_t num_5;
  rational_t num_6;
  rational_t num_7;
  rational_t num_8;

  stringx str_1;
  stringx str_2;
  stringx str_3;
  stringx str_4;

  vector3d vec_1;
  vector3d vec_2;

public:
  virtual bool get_ifc_vec(const pstring &att, vector3d &val);
};

#define IFC_INTERNAL_GET_MACRO(a,b)       { static pstring pstring_get(a);  if(att == pstring_get)  { val = b; return(true); } }

bool script_data_interface::get_ifc_vec(const pstring &att, vector3d &val)
{
  IFC_INTERNAL_GET_MACRO("SD_VEC_1", vec_1);
  IFC_INTERNAL_GET_MACRO("SD_VEC_2", vec_2);

  return(false);
}
